import{_ as a,o as d,c as e,a2 as r}from"./chunks/framework.DSoq407f.js";const p=JSON.parse('{"title":"系统设置","description":"","frontmatter":{},"headers":[],"relativePath":"admin/settings.md","filePath":"admin/settings.md","lastUpdated":1786543008000}'),i={name:"admin/settings.md"};function l(o,t,h,s,n,c){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="系统设置" tabindex="-1">系统设置 <a class="header-anchor" href="#系统设置" aria-label="Permalink to &quot;系统设置&quot;">​</a></h1><blockquote><p>配置平台级的系统参数。</p></blockquote><h2 id="站点设置" tabindex="-1">站点设置 <a class="header-anchor" href="#站点设置" aria-label="Permalink to &quot;站点设置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>配置</th><th>说明</th></tr></thead><tbody><tr><td>站点名称</td><td>显示在页面的品牌名</td></tr><tr><td>Logo</td><td>站点标志</td></tr><tr><td>备案信息</td><td>ICP 备案号（底部展示）</td></tr><tr><td>联系方式</td><td>客服 QQ / 邮箱等</td></tr></tbody></table><h2 id="邮件设置" tabindex="-1">邮件设置 <a class="header-anchor" href="#邮件设置" aria-label="Permalink to &quot;邮件设置&quot;">​</a></h2><p>配置 SMTP，用于系统邮件（注册验证、密码重置、通知等）：</p><table tabindex="0"><thead><tr><th>配置</th><th>说明</th></tr></thead><tbody><tr><td>SMTP 服务器</td><td>如 <code>smtp.qq.com</code></td></tr><tr><td>端口</td><td>465（SSL）/ 587（TLS）</td></tr><tr><td>发件账号</td><td>邮箱地址</td></tr><tr><td>授权码</td><td>邮箱的 SMTP 授权码</td></tr><tr><td>发件人名称</td><td>显示名</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">先测试再启用</p><p>配置完 SMTP 后，先用测试邮件功能发一封验证能否正常收发，再开启依赖邮件的功能。</p></div><h2 id="支付设置" tabindex="-1">支付设置 <a class="header-anchor" href="#支付设置" aria-label="Permalink to &quot;支付设置&quot;">​</a></h2><p>配置彩虹易支付（见<a href="./subscriptions#支付配置">订阅与计费</a>）：</p><ul><li>接口地址、商户号、密钥。</li><li>协议版本（V1 MD5 / V2 RSA）。</li><li>充值档位、自定义金额范围。</li></ul><h2 id="redis-设置" tabindex="-1">Redis 设置 <a class="header-anchor" href="#redis-设置" aria-label="Permalink to &quot;Redis 设置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>配置</th><th>说明</th></tr></thead><tbody><tr><td>Redis 地址</td><td>连接 URL</td></tr><tr><td>启用 / 停用</td><td>是否启用 Redis 加速</td></tr></tbody></table><p>Redis 不可用时自动降级为数据库轮询（见<a href="./../deploy/requirements#可选组件">环境要求</a>）。</p><h2 id="注册设置" tabindex="-1">注册设置 <a class="header-anchor" href="#注册设置" aria-label="Permalink to &quot;注册设置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>配置</th><th>说明</th></tr></thead><tbody><tr><td>开放注册</td><td>是否允许新用户注册</td></tr><tr><td>邮箱验证</td><td>注册是否强制邮箱验证</td></tr><tr><td>注册赠送</td><td>新用户赠送余额 / 试用订阅</td></tr><tr><td>邀请奖励</td><td>邀请新用户的奖励</td></tr></tbody></table><h2 id="维护模式" tabindex="-1">维护模式 <a class="header-anchor" href="#维护模式" aria-label="Permalink to &quot;维护模式&quot;">​</a></h2><p>开启后，除白名单接口外，所有访问返回维护中提示：</p><ul><li>用于系统升级、数据迁移时临时屏蔽用户访问。</li><li>公共回调（如支付回调）仍可正常工作。</li></ul><div class="warning custom-block"><p class="custom-block-title">维护模式期间</p><p>开启维护模式会让普通用户无法使用。升级完成后记得关闭。</p></div><h2 id="ip-黑名单" tabindex="-1">IP 黑名单 <a class="header-anchor" href="#ip-黑名单" aria-label="Permalink to &quot;IP 黑名单&quot;">​</a></h2><p>封禁恶意 IP，被拉黑的 IP 无法访问平台。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>查看配置是否生效 → 各功能页验证</li><li>配置出问题排查 → <a href="./../deploy/ops">运维与备份</a></li></ul>',24)])])}const u=a(i,[["render",l]]);export{p as __pageData,u as default};
